      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n8월~9월말) 수도권 거주 20~50대 남/여) 통신사 이용고객 관련 다이어리 + 홈비짓\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.21. 16:36\n조회 82\n구독\n8월~9월말) 수도권 거주 20~50대 남/여) 통신사 이용고객 관련 다이어리 + 홈비짓\n신청하신분은 재신청 안하셔도 됩니다\n8월~9월초 유선통신 해지후 타 통신사로 전환가입예정자 급\n수도권 거주 20~50대 남/여\n향후 2개월 내에 통신 유선상품 해지 및 가입설치자 (초고속인터넷 / IPTV) 조사\n[조건]\n* KT 상품 해지 후 U+로 전환 가입예정자 (3명)\n* LGU+ 해지후 KT 전환 가입예정자 (3명)\n조사일정 : 8월~9월말\n(다이어리 작성후 참여자가 원하는 날짜에 집에 방문하여 설치기사 설치 과정 참관후 인터뷰 진행예정)\n소요시간 : 2시간\n사례비 : 15 만원(홈비짓) + 다이어리 (7만원)\n조사방식 : 다이어리 + 홈비짓\n* 신청시 아래의 URL로 신청 부탁 드리고, 소개자에 꼭 이름 써주세요!\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://ms.esurvey.kr/?ACCESS_KEY=b12c4b652f7b496a94b6\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n인테리어/마감공사 관련 근무자 인터뷰\n좌담회알바좌담회카페\n26.08.21.\n댓글\n0\n8월~9월말) 수도권 거주 20~50대 남/여) 통신사 이용고객 관련 다이어리 + 홈비짓\n좌담회알바좌담회카페\n26.08.21.\n댓글\n0\n20~59세 수도권 소상공인 사장님(경영주)-매장에서 전화 + cctv가 모두 SK/KT/LG 3사통신사중 한곳 이용하시는 사장님\n좌담회알바좌담회카페\n26.08.21.\n댓글\n1\n9/2) 20~60세 여성 ) 미용/에스테틱/비만 치료제(위고비,마운자로,석센다) 좌담회\n좌담회알바좌담회카페\n26.08.21.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
