      "raw_content": "미용·에스테틱 좌담회-만20~60세 남녀 9/2[사례비 추후안내]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n►대상 : 지난 12개월 이내 미용 피부과 또는 피부과 중심 에스테틱에서 아래 5개 분야의 서비스를 1개 이상 받은 성인 20~60세 여자대상\n<아래 시술에서만 해당 됩니다>\n예시: 보톡스(X) 보톡스(디스포트(0)\n1. 주사 시술->\n1)보톡스( 보톡스, 디스포트, 제오민, 보톨락스, 나보타, 코레톡스, 이너톡스)\n2)필러( 쥬비덤, 레스틸렌, RHA 테옥산, 뉴라미스, 이부아르)\n3)바이오자극제( 스컬트라, 라디에스, 쥬벨룩 볼륨, 애스더필)\n2. 바디 컨투어링->\n4)비침습 지방 감소( 쿨스컬프팅, 클라투 알파, 리포소닉스)\n5)피부 탄력 개선( 울쎄라, 써마지 FLX, 슈링크 유니버스, 티타늄 리프팅)\n6)근육 자극(Emsculpt, CoreSculpt)\n3. 모발 복원->\n7)처방 구소 및 경구용 제제(피나스테리드, 두타스테리드, 미녹시딜)\n8)혈소판 풍부 혈장(PRP)\n9)모발 이식 수술자\n4. 치료용 레이저->\n10)피부 재생(프락셀, CO2, 레이저 MD 울트라)\n11)색소침착 교정(피코플러스/피코웨이,레블라이트SL,할리우드 레이저필)\n12)혈관 및 주사(Vbeam, Excel V, Excel V+)\n5. 비만 치료제->\n13)위고비, 마운자로, 석센다 복용자\n►일정 :\n1.그룹 : 45~60세 여성 ->9월 2일(수) 오후 4시\n2.그룹 : 35~44세 여성 ->9월 2일(수) 오후 6시 15분\n3.그룹 : 20~34세 여성->9월 2일(수) 저녁 8시\n►소요 시간: 1시간 15분\n►장소 : 6호선 상수역 부근\n►사례비 : 컨택시\n​\n신청하기",
