      "raw_content": "성인 초기 커플 갈등·상호작용 경험 연구-만19세 이상 미혼 커플 일정조율[1인당 20만원]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n대상 : 만19세 이상 성인 남녀 커플\n커플 모두 참여 필요\n부부 참여 불가\n최근 1년 이내 교제 관계에서 갈등 혹은 폭력 경험이 있었던 분\n커플 양측 모두 연구 참여에 동의한 경우\n일정 : 조율하여 진행\n방법 : 사전 인터뷰 및 설명 동의(온라인) → 연구 적합성 및 안전성 확인 → 2주간 모바일 기반 일상 기록(하루 약 5분 내외) → 커플 상호작용 인터뷰 (60~90분 / 비디오 촬영 20분 내외, 참여자 인근 스터디카페·스튜디오 또는 참여자와 상의하여 장소 협의)\n​\n소요시간 : 총 3시간 내외\n사례비 : 1인당 20만원 (커플당 40만원)\n장소 : 참여자 인근 스터디카페·스튜디오 또는 참여자와 상의하여 협의\n안내사항\n* 중간에 연구 참여를 그만두는 경우 보상 지급이 어렵습니다.\n* 연구 적합성 및 안전성 확인 과정에서 연구 참여자를 선별합니다.\n선별 과정에서 선별되지 않으실 경우\n네이버페이 500 포인트 교환권\n을 드립니다.\n* 신청 후 선별 과정에 참여하지 않게 될 수도 있으며, 이 경우에는 보상 지급이 되지 않는 점 참고 부탁드립니다.\n​\n신청하기",
